package com.fitnutri.backend.records;

import com.fasterxml.jackson.databind.*;
import com.fitnutri.backend.activity.ActivityReferenceImportService;
import com.fitnutri.backend.support.TestDatabase;
import com.fitnutri.backend.user.UserRepository;
import com.fitnutri.backend.submission.SubmissionReceiptRepository;
import java.net.*;
import java.net.http.*;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.core.io.*;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;

/** Official source, actual Session/CSRF/MVC/PG. React end-to-end is a separate later gate. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @ActiveProfiles("integration-test") @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ExerciseRecordingHttpIntegrationTest {
    private static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
    @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
    @LocalServerPort int port;@Autowired ActivityReferenceImportService importer;@Autowired UserRepository users;@Autowired ExerciseRecordRepository records;@Autowired SubmissionReceiptRepository receipts;@Autowired com.fitnutri.backend.activity.ExerciseTypeRepository types;
    private final ObjectMapper json=new ObjectMapper();private HttpClient client;private String csrf,email;
    @BeforeAll void verifiedSource() throws Exception {Path dir=Path.of(System.getenv().getOrDefault("TEST_REFERENCE_SOURCE_DIR",Path.of("..",".local","reference-sources").toString())).toAbsolutePath().normalize();Map<String,Resource> raw=new HashMap<>();for(String name:List.of("2024-adult-compendium.pdf","2024-adult-compendium-age-source.html"))raw.put(name,new FileSystemResource(dir.resolve(name)));assertEquals(15,importer.importActivityManifest(new ClassPathResource("data/manifests/compendium-2024-r1.json"),new ClassPathResource("data/compendium-2024-activities-r1.json"),raw).importedCount());}
    @BeforeEach void signedInAdult() throws Exception {client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();csrf=null;email="http-exercise-"+UUID.randomUUID()+"@example.test";csrf=status(200,send("GET","/api/auth/csrf",null)).get("token").asText();status(201,send("POST","/api/auth/register",Map.of("email",email,"password","Synthetic123","displayName","Synthetic HTTP exercise")));status(200,send("POST","/api/auth/login",Map.of("email",email,"password","Synthetic123")));csrf=status(200,send("GET","/api/auth/csrf",null)).get("token").asText();var setup=settings(status(200,send("GET","/api/profile",null)),1990);setup.put("initialWeight",Map.of("recordDate","2020-01-02","weightKg",70));status(200,send("POST","/api/profile/onboarding",setup));}
    private Map<String,Object> settings(JsonNode profile,int birth){var body=new LinkedHashMap<String,Object>();body.put("expectedUserVersion",profile.get("user").get("version").asLong());body.put("expectedProfileVersion",profile.get("profileVersion").isNull()?null:profile.get("profileVersion").asLong());body.put("displayName","Synthetic HTTP exercise");body.put("birthYear",birth);body.put("adultConfirmed",true);body.put("sex","PREFER_NOT_TO_SAY");body.put("heightCm",170);body.put("activityLevel","LIGHT");body.put("goalType",null);body.put("dailyTargetKj",null);body.put("energyUnit","KJ");body.put("healthSafetyAnswer","NO");body.put("qaConsentGranted",false);body.put("zone","Australia/Sydney");return body;}
    private HttpResponse<String> send(String method,String path,Object body) throws Exception {var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path));if(csrf!=null)r.header("X-CSRF-TOKEN",csrf);if(body!=null)r.header("Content-Type","application/json");return client.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
    private JsonNode status(int expected,HttpResponse<String> r) throws Exception {assertEquals(expected,r.statusCode(),r.body());return json.readTree(r.body());}
    private String walking() throws Exception {var types=status(200,send("GET","/api/records/exercise/types",null));assertEquals(15,types.size());for(var type:types)if(type.get("activityKey").asText().equals("walking")){assertEquals("17160",type.get("sourceActivityCode").asText());assertEquals(3.5,type.get("metValue").asDouble());return type.get("id").asText();}throw new AssertionError("Official walking preset missing");}
    private JsonNode preview(String id,String date,String minutes) throws Exception {return status(200,send("GET","/api/records/exercise/estimate?exerciseTypeId="+id+"&recordDate="+date+"&durationMinutes="+minutes+"&zone=Australia%2FSydney",null));}
    private Map<String,Object> request(JsonNode preview){return new LinkedHashMap<>(Map.of("submissionId",UUID.randomUUID().toString(),"recordDate",preview.get("recordDate").asText(),"zone","Australia/Sydney","source","MANUAL","exerciseTypeId",preview.get("exerciseType").get("id").asText(),"durationMinutes",preview.get("durationMinutes").decimalValue(),"clientEntryId",UUID.randomUUID().toString(),"calculationFingerprint",preview.get("calculationFingerprint").asText()));}
    private Long owner(){return users.findByCanonicalEmail(email).orElseThrow().getId();}
    @Test void officialPresetDatedPreviewAndReviewedSaveReturnExactSnapshotAndReplay() throws Exception {var p=preview(walking(),"2020-01-02","10.50");assertEquals(179.389,p.get("estimatedKj").asDouble());assertEquals("2020-01-02",p.get("weightDateUsed").asText());var request=request(p);var first=status(201,send("POST","/api/records/exercise",request));assertEquals("EXERCISE_CREATE",first.get("kind").asText());var replay=status(200,send("POST","/api/records/exercise",request));assertTrue(replay.get("replayed").asBoolean());assertEquals(first.get("records"),replay.get("records"));assertEquals(first.get("records"),status(200,send("GET","/api/submissions/"+request.get("submissionId"),null)).get("records"));var rows=records.findByUserIdOrderByRecordedAtDesc(owner());assertEquals(1,rows.size());assertEquals(new java.math.BigDecimal("179.389"),rows.getFirst().getEstimatedKj());assertEquals(new java.math.BigDecimal("70.00"),rows.getFirst().getWeightKgUsed());assertNull(rows.getFirst().getIntensity());
        var listed=status(200,send("GET","/api/records/exercise?from=2020-01-02&to=2020-01-02",null));assertEquals(1,listed.size());String id=listed.get(0).get("id").asText();var detail=status(200,send("GET","/api/records/exercise/"+id,null));assertEquals(listed.get(0),detail);assertEquals("17160",detail.get("exerciseType").get("sourceActivityCode").asText());assertFalse(detail.has("intensity"));assertFalse(detail.has("estimatedCalories"));status(200,send("POST","/api/profile/weight",Map.of("recordDate","2020-01-02","weightKg",80,"expectedVersion",0,"zone","Australia/Sydney")));var historical=status(200,send("GET","/api/records/exercise/"+id,null));assertEquals(179.389,historical.get("estimatedKj").asDouble());assertEquals(70,historical.get("weightKgUsed").asInt());}
    @Test void correctedWeightRequiresExplicitNewReviewWithFreshSubmissionAndNoPartialOldSave() throws Exception {var p=preview(walking(),"2020-01-02","10");var request=request(p);status(200,send("POST","/api/profile/weight",Map.of("recordDate","2020-01-02","weightKg",80,"expectedVersion",0,"zone","Australia/Sydney")));var conflict=status(409,send("POST","/api/records/exercise",request));assertEquals("CALCULATION_CHANGED",conflict.get("code").asText());assertEquals(8,conflict.size());assertEquals(80,conflict.get("currentPreview").get("weightKgUsed").asInt());assertEquals(195.253,conflict.get("currentPreview").get("estimatedKj").asDouble());assertTrue(records.findByUserIdOrderByRecordedAtDesc(owner()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(owner(),UUID.fromString((String)request.get("submissionId"))).isEmpty());request.put("submissionId",UUID.randomUUID().toString());request.put("calculationFingerprint",conflict.get("currentPreview").get("calculationFingerprint").asText());status(201,send("POST","/api/records/exercise",request));assertEquals(new java.math.BigDecimal("195.253"),records.findByUserIdOrderByRecordedAtDesc(owner()).getFirst().getEstimatedKj());}
    @Test void missingWeightAndSourceAgeFailureSaveActivitiesWithHonestNullEnergy() throws Exception {String type=walking();var missing=preview(type,"2020-01-01","10");assertEquals("MISSING_WEIGHT",missing.get("estimateStatus").asText());assertTrue(missing.get("estimatedKj").isNull());status(201,send("POST","/api/records/exercise",request(missing)));status(200,send("PUT","/api/profile",settings(status(200,send("GET","/api/profile",null)),2002)));var age=preview(type,"2020-01-01","10");assertEquals("NO_APPLICABLE_REFERENCE",age.get("estimateStatus").asText());assertTrue(age.get("estimatedKj").isNull());status(201,send("POST","/api/records/exercise",request(age)));var rows=records.findByUserIdOrderByRecordedAtDesc(owner());assertEquals(2,rows.size());assertTrue(rows.stream().allMatch(r->r.getEstimatedKj()==null));}
    @Test void rangeTypeFilterAndDetailsStayOwnedAndOldNameFilterIsExplicitlyRejected() throws Exception {
        String type=walking();var saved=status(201,send("POST","/api/records/exercise",request(preview(type,"2020-01-02","10"))));String id=saved.get("records").get(0).get("id").asText();assertEquals(1,status(200,send("GET","/api/records/exercise?from=2020-01-02&to=2020-01-02&exerciseTypeId="+type,null)).size());assertEquals(0,status(200,send("GET","/api/records/exercise?from=2020-01-02&to=2020-01-02&exerciseTypeId=999999999",null)).size());status(400,send("GET","/api/records/exercise?from=2020-01-02&to=2020-01-02&exerciseType=Walking",null));
        signedInAdult();assertEquals("NOT_FOUND",status(404,send("GET","/api/records/exercise/"+id,null)).get("code").asText());assertEquals(0,status(200,send("GET","/api/records/exercise?from=2020-01-02&to=2020-01-02",null)).size());status(400,send("GET","/api/records/exercise?to=2020-01-02",null));
    }
    @Test void correctedDateRequiresReviewAndNoOpDeleteReplayNeverRewriteCreationProof() throws Exception {
        String type=walking();var initialPreview=preview(type,"2020-01-02","10");var original=request(initialPreview);var proof=status(201,send("POST","/api/records/exercise",original));String id=proof.get("records").get(0).get("id").asText();var weight=new LinkedHashMap<String,Object>();weight.put("recordDate","2020-01-03");weight.put("weightKg",80);weight.put("expectedVersion",null);weight.put("zone","Australia/Sydney");status(201,send("POST","/api/profile/weight",weight));var body=new LinkedHashMap<String,Object>(Map.of("expectedVersion",0,"exerciseTypeId",type,"durationMinutes",10,"recordDate","2020-01-03","zone","Australia/Sydney","calculationFingerprint",initialPreview.get("calculationFingerprint").asText()));var conflict=status(409,send("PUT","/api/records/exercise/"+id,body));assertEquals("CALCULATION_CHANGED",conflict.get("code").asText());assertEquals(195.253,conflict.get("currentPreview").get("estimatedKj").asDouble());assertEquals("2020-01-02",status(200,send("GET","/api/records/exercise/"+id,null)).get("recordDate").asText());body.put("calculationFingerprint",conflict.get("currentPreview").get("calculationFingerprint").asText());var changed=status(200,send("PUT","/api/records/exercise/"+id,body));assertEquals(1,changed.get("version").asInt());body.put("expectedVersion",1);body.remove("calculationFingerprint");assertEquals(changed,status(200,send("PUT","/api/records/exercise/"+id,body)));body.put("expectedVersion",0);assertEquals("VERSION_CONFLICT",status(409,send("PUT","/api/records/exercise/"+id,body)).get("code").asText());assertEquals(204,send("DELETE","/api/records/exercise/"+id+"?expectedVersion=1",null).statusCode());assertEquals(204,send("DELETE","/api/records/exercise/"+id+"?expectedVersion=1",null).statusCode());status(404,send("GET","/api/records/exercise/"+id,null));assertEquals(proof.get("records"),status(200,send("POST","/api/records/exercise",original)).get("records"));assertNotNull(records.findById(Long.valueOf(id)).orElseThrow().getDeletedAt());
    }
    @Test void inactiveOriginalActivityCanBeReviewedAndCorrectedOnlyByItsOwner() throws Exception {
        String type=walking();var proof=status(201,send("POST","/api/records/exercise",request(preview(type,"2020-01-02","10"))));String id=proof.get("records").get(0).get("id").asText();var source=types.findById(Long.valueOf(type)).orElseThrow();source.setActive(false);types.saveAndFlush(source);
        try {status(409,send("GET","/api/records/exercise/estimate?exerciseTypeId="+type+"&durationMinutes=20&recordDate=2020-01-02",null));var p=status(200,send("GET","/api/records/exercise/estimate?exerciseTypeId="+type+"&durationMinutes=20&recordDate=2020-01-02&recordId="+id,null));assertFalse(p.get("exerciseType").get("active").asBoolean());assertEquals(341.693,p.get("estimatedKj").asDouble());var body=Map.of("expectedVersion",0,"exerciseTypeId",type,"durationMinutes",20,"recordDate","2020-01-02","zone","Australia/Sydney","calculationFingerprint",p.get("calculationFingerprint").asText());status(200,send("PUT","/api/records/exercise/"+id,body));assertEquals("REFERENCE_INACTIVE",status(409,send("POST","/api/records/exercise",request(p))).get("code").asText());signedInAdult();assertEquals("NOT_FOUND",status(404,send("GET","/api/records/exercise/estimate?exerciseTypeId="+type+"&durationMinutes=20&recordDate=2020-01-02&recordId="+id,null)).get("code").asText());}
        finally {source.setActive(true);types.saveAndFlush(source);}
    }
}
